package com.gameaggregator.entitlementservice.application;import com.gameaggregator.platform.core.common.exception.NotFoundException;import com.gameaggregator.entitlementservice.api.EntitlementDtos.*;import com.gameaggregator.entitlementservice.domain.Entitlement;import com.gameaggregator.entitlementservice.infrastructure.EntitlementRepository;import java.time.LocalDate;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service @Transactional public class EntitlementService{final EntitlementRepository repo;public EntitlementService(EntitlementRepository r){repo=r;}public Entitlement create(Create r){if(r.endDate()!=null&&r.endDate().isBefore(r.startDate()))throw new IllegalArgumentException("End date must not precede start date");return repo.save(new Entitlement(r.clientId(),r.gameId(),r.environmentId(),r.region(),r.startDate(),r.endDate(),r.contractReference()));}public List<Entitlement> client(UUID id){return repo.findAllByClientId(id);}public Entitlement status(UUID id,Status r){var e=repo.findById(id).orElseThrow(()->new NotFoundException("ENTITLEMENT_NOT_FOUND","Entitlement was not found"));e.status=r.status();return e;}public Decision check(UUID c,UUID g,UUID e,String region){boolean active=repo.existsByClientIdAndGameIdAndEnvironmentIdAndRegionAndStatus(c,g,e,region,"ACTIVE");return new Decision(active,active?"ACTIVE_ENTITLEMENT":"NO_ACTIVE_ENTITLEMENT");}}